def solve():
    exotic = set()
    for k in range(1000):
        exotic.add((2*k+1)**2)
    for z in range(1, 1000):
        exotic.add(2 * (z**2))

    sorted_exotic = sorted(list(exotic))
    return sorted_exotic[:20]

print(solve())

def count_divisors(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i*i != n:
                count += 1
    return count

for n in range(1, 11):
    d_n = count_divisors(n)
    print(f"n={n}, d(n)={d_n}, 2*d(n)={2*d_n}, is_exotic={d_n % 2 == 1}")
